//! Closed CQ13. Uses the original event queue, paid contest, and removal wave.
use crate::{catalog,engine::RuleResult,model::*,rules::*,mystic_contest::ContestOutcome};
use std::collections::BTreeSet;
pub(crate) const ID:&str="CQ13";
pub(crate) const ENTRY:&str="cq13-clock-entry";
pub(crate) const CONTEST:&str="cq13-contest-blink";
pub(crate) const LEAVE:&str="cq13-leave-destroy";
fn same<T:serde::Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
fn region(destroyed:bool)->TargetSlotSpec{let mut t=target(Zone::Region,EntityKind::Any,Relation::Any,Range::Anywhere);if destroyed{t.predicate=Some(TargetPredicate::CQ13DestroyedRegion);}t}
pub(crate) fn definition()->Definition{
 let mut e=ability(ENTRY,"进场：本方末日钟时毁灭地区或在已毁灭地区放势力",Timing::Fast,vec![],vec![],vec![],Some(Event::Enter));
 e.modes=vec![Mode{key:"destroy".into(),label:"毁灭目标地区".into(),targets:vec![region(false)],ops:vec![Op::CQ13Entry{influence:false}]},Mode{key:"influence".into(),label:"在已毁灭地区放本方势力".into(),targets:vec![region(true)],ops:vec![Op::CQ13Entry{influence:true}]}];
 let mut a=ability(CONTEST,"快速③：隐秘对抗，获胜则闪烁",Timing::Fast,vec![Cost::Assets(3)],vec![],vec![Op::MysticContest{actor_bonus:0}],None);a.activation_only=true;
 with_abilities(vec![e,a,ability(LEAVE,"离场强制：消灭本地区所有其他角色",Timing::Fast,vec![],vec![],vec![Op::CQ13Leave],Some(Event::Leave))])
}
fn owns(o:&Op)->bool{match o{Op::CQ13Entry{..}|Op::CQ13Leave=>true,Op::ForEachLivingPlayer(v)|Op::ForEachLivingPlayerFromActor(v)=>v.iter().any(owns),Op::IfTargetExhausted{exhausted,ready,..}=>owns(exhausted)||owns(ready),_=>false}}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("cq13-")||a.ops.iter().chain(a.modes.iter().flat_map(|m|&m.ops)).any(owns)}
fn variants()->Vec<AbilitySpec>{let d=definition();let mut v=d.abilities.clone();for a in d.abilities{for m in &a.modes{let mut b=a.clone();b.label=format!("{}：{}",b.label,m.label);b.modes.clear();b.targets=m.targets.clone();b.ops=m.ops.clone();v.push(b);}}v}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{if id!=ID||!variants().iter().any(|b|same(a,b)){return Err("薇儿丹迪原程序、费用或模式损坏".into())}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if(id==ID||d.abilities.iter().any(related))&&(id!=ID||!same(d,&definition())){return Err("薇儿丹迪定义不可改写或移植".into())}Ok(())}
fn owned(f:&ResolutionFrame)->bool{f.ability_key.starts_with("cq13-")||f.steps.iter().any(|s|owns(&s.op))}
impl Game{
 fn cq13_source(&self,actor:usize,s:&SourceSnapshot)->RuleResult<()>{let c=&s.card;if c.definition!=ID||actor>=self.players.len()||c.controller!=actor||c.owner>=self.players.len()||c.face_down||!self.mystic_instance_valid(&c.id)||s.region.is_none_or(|r|r>=self.regions.len())||s.source_region_instance.as_deref().is_none_or(|s|!self.mystic_instance_valid(s))||s.play_source.is_some()||s.attachment_host_instance.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some(){return Err("薇儿丹迪原地区来源损坏".into())}self.mobility_immutable_identity(c)}
 pub(crate) fn cq13_declare(&mut self,d:&Declaration)->RuleResult<bool>{if !related(&d.ability){return Ok(false)}validate_ability(&d.source.card.definition,&d.ability)?;self.cq13_source(d.actor,&d.source)?;if d.ability.key==ENTRY{return Ok(!self.msjz03_active(d.actor))}if d.ability.key!=LEAVE{return Err("薇儿丹迪行动不能伪装触发".into())}if !self.players[d.actor].eliminated{let f=self.make_frame(d.actor,d.source.clone(),&d.ability,vec![],vec![],None);self.dispatch_frame(f,d.ability.label.clone(),None,ResponsePolicy::Respondable);}Ok(true)}
 pub(crate) fn cq13_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if !owned(f){if f.source.card.definition==ID&&!matches!(f.ability_key.as_str(),"deploy"|"reveal")&&!self.validated_cross_card_frame(f)?{return Err("薇儿丹迪不能使用外来源帧".into())}return Ok(())}self.cq13_source(f.actor,&f.source)?;self.validate_resource_frame(f)?;
 let a=variants().into_iter().find(|a|a.key==f.ability_key&&a.modes.is_empty()&&same(&f.steps,&a.ops.iter().map(|o|Step{context:f.actor,op:o.clone()}).collect::<Vec<_>>())&&same(&a.targets,&f.targets.iter().map(|t|t.spec.clone()).collect::<Vec<_>>())).ok_or("薇儿丹迪帧程序错配")?;
 let paid=if a.key==CONTEST{matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)]if ids.iter().collect::<BTreeSet<_>>().len()==ids.len()&&ids.iter().all(|s|self.mystic_instance_valid(s)&&s!=&f.source.card.id))&&f.money_units(0)==3}else{f.already_paid.is_empty()&&f.resource_payments.is_empty()};
 if !paid||!self.mystic_instance_valid(&f.frame_id)||f.frame_id==f.source.card.id||f.cursor>1||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor==1&&!matches!(f.guard,GuardState::Accepted){return Err("薇儿丹迪费用或续体阶段损坏".into())}
 if a.key==ENTRY{let t=&f.targets[0];let r=t.id.strip_prefix("region:").and_then(|n|n.parse::<usize>().ok()).filter(|r|*r<self.regions.len()).ok_or("薇儿丹迪地区目标损坏")?;if t.id!=format!("region:{r}")||f.chosen_region.is_some()||t.public.region!=Some(r)||t.public.instance_id!=t.id||t.public.kind!="region"||!t.public.valid||t.public.status!="valid"||t.public.invalid_reason.is_some()||t.region_instance.as_deref().is_none_or(|s|!self.mystic_instance_valid(s)){return Err("薇儿丹迪须绑定原地区实体".into())}}else if f.chosen_region.is_some(){return Err("薇儿丹迪无额外地区选择".into())}Ok(())
 }
 pub(crate) fn cq13_step(&mut self,f:&ResolutionFrame,influence:Option<bool>)->RuleResult<()>{self.cq13_frame(f)?;if f.cursor!=1{return Err("薇儿丹迪须消费原步骤".into())}if let Some(add)=influence{if !self.msjz03_active(f.actor){return Ok(())}let t=&f.targets[0];if self.valid_bound_target(f.actor,&f.source,t){let r=t.id.strip_prefix("region:").unwrap().parse::<usize>().unwrap();if add{self.place_influence(f.actor,r,1);}else{self.regions[r].destroyed=true;}}}else{self.jc052_destroy_others(f);}Ok(())}
 pub(crate) fn cq13_after(&mut self,f:&ResolutionFrame,o:&ContestOutcome)->RuleResult<()>{if f.ability_key!=CONTEST{return Ok(())}self.cq13_frame(f)?;if o.frame_id!=f.frame_id||o.ability_key!=CONTEST||!same(&o.source,&f.source){return Err("薇儿丹迪须绑定原次隐秘对抗".into())}if o.winner_team==Some(self.team(f.actor))&&self.board(&f.source.card.id).is_some_and(|(_,c)|!c.face_down&&c.definition==ID){if let Some(c)=self.hide_in_place_successor(&f.source.card.id){self.world_reveal(c.controller,&c.id,false)?;}}Ok(())}
 fn cq13_play_frame(&self,f:&ResolutionFrame)->RuleResult<()>{self.validate_resource_frame(f)?;let s=&f.source;let c=&s.card;let reveal=f.ability_key=="reveal";
 if c.definition!=ID||f.actor>=self.players.len()||c.owner>=self.players.len()||c.controller!=f.actor||!self.mystic_instance_number(&c.id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b)||f.cursor!=0||!matches!(f.guard,GuardState::Unchecked)||!f.steps.is_empty()||!f.targets.is_empty()||s.attachment_host_instance.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some()||f.chosen_region!=s.region||if reveal{!c.face_down||s.play_source.is_some()||s.region.is_none_or(|r|r>=self.regions.len())||s.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))}else{f.ability_key!="deploy"||c.face_down||!s.valid_character_play()||s.region.is_none_or(|r|r>=self.regions.len())||s.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))}||!matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)]if f.money_units(0)<=7&&ids.iter().collect::<BTreeSet<_>>().len()==ids.len()&&ids.iter().all(|id|self.mystic_instance_valid(id)&&id!=&c.id)){return Err("薇儿丹迪原派遣/现身事务损坏".into());}self.mobility_immutable_identity(c)
 }
 pub(crate) fn validate_cq13_play(&self,i:&StackItem)->RuleResult<()>{if i.card.as_ref().is_some_and(|c|c.definition==ID)||i.frame.as_ref().is_some_and(|f|f.source.card.definition==ID&&matches!(f.ability_key.as_str(),"deploy"|"reveal")){let f=i.frame.as_ref().ok_or("薇儿丹迪实际角色事务缺帧")?;self.cq13_play_frame(f)?;if i.id!=f.frame_id||i.controller!=f.actor||i.target.is_some()||i.reveal!=(f.ability_key=="reveal")||i.deploy_region!=f.chosen_region||i.card.as_ref().is_none_or(|c|!self.pack_a_transaction_matches(f,c)){return Err("薇儿丹迪实际事务与原帧不符".into());}}Ok(())}
 pub(crate) fn validate_cq13_state(&self)->RuleResult<()>{let mut seen=BTreeSet::new();let mut check=|f:&ResolutionFrame|->RuleResult<()>{self.cq13_frame(f)?;if owned(f)&&!seen.insert(f.frame_id.clone()){return Err("薇儿丹迪同帧重复续体".into())}Ok(())};for i in &self.stack{self.validate_cq13_play(i)?;if let Some(f)=&i.frame{check(f)?;if owned(f)&&(i.card.is_some()||i.id!=f.frame_id||i.controller!=f.actor||i.reveal||i.deploy_region.is_some()||f.cursor!=0){return Err("薇儿丹迪响应外壳损坏".into())}}}for e in &self.effects{match e{Effect::Frame{frame}=>check(frame)?,Effect::Declare{declaration:d}if related(&d.ability)=>{validate_ability(&d.source.card.definition,&d.ability)?;self.cq13_source(d.actor,&d.source)?;if d.ability.key==CONTEST{return Err("薇儿丹迪行动不属于触发".into())}},_=>()}}for s in self.mystic_states(){check(&s.frame)?;}if let Some(p)=&self.pending{match &p.resolution{ChoiceResolution::Declare{declaration:d,stage}if related(&d.ability)=>{validate_ability(&d.source.card.definition,&d.ability)?;self.cq13_source(d.actor,&d.source)?;if d.ability.key!=ENTRY{return Err("薇儿丹迪离场不能可选".into())}let opts=match stage{DeclareChoice::Mode if !d.ability.modes.is_empty()=>d.ability.modes.iter().filter(|m|m.targets.first().is_none_or(|t|!self.binding_options(d.actor,&d.source,t).is_empty())).map(|m|ChoiceOption{id:m.key.clone(),label:m.label.clone(),card:None}).collect(),DeclareChoice::Target if d.ability.modes.is_empty()=>self.binding_options(d.actor,&d.source,&d.ability.targets[0]),_=>return Err("薇儿丹迪进场待选阶段错误".into())};let expected=Choice{id:p.choice.id.clone(),kind:"trigger".into(),title:format!("{}：{}",crate::batch3_trap::source_label(&d.source),d.ability.label),description:"选择符合数量限制的选项，然后确认。".into(),player_id:player_id(d.actor),options:opts,preview_cards:vec![],min:Some(0),max:Some(1),amount:None,allow_decline:Some(true)};if p.seat!=d.actor||!self.mystic_instance_valid(&p.choice.id)||!same(&expected,&p.choice){return Err("薇儿丹迪待选玩家或目标外壳损坏".into())}},ChoiceResolution::Frame{frame,..}=>{self.cq13_frame(frame)?;},_=>()}}Ok(())}
}
